int visitFrameStart(final int offset, final int numLocal, final int numStack) {
    // Validate inputs to avoid encoding negatives or unrealistic sizes.
    if (offset < 0) {
        throw new IllegalArgumentException("offset must be non‑negative. Provided: " + offset);
    }
    if (numLocal < 0) {
        throw new IllegalArgumentException("numLocal must be non‑negative. Provided: " + numLocal);
    }
    if (numStack < 0) {
        throw new IllegalArgumentException("numStack must be non‑negative. Provided: " + numStack);
    }

    /*
     * The format for a stack‑map frame (in this simplified implementation) is:
     *
     *  - 4 bytes: offset (big‑endian)
     *  - 4 bytes: number of local variables (big‑endian)
     *  - 4 bytes: number of stack entries (big‑endian)
     *
     * After these 12 bytes we will add the actual descriptor entries for locals
     * and stack. The method returns the index of the next writable element, which
     * is therefore 12.
     */
    final int FRAME_HEADER_BYTES = 12;
    currentFrame = new byte[FRAME_HEADER_BYTES];

    // Encode the offset as big‑endian.
    currentFrame[0] = (byte) ((offset >>> 24) & 0xFF);
    currentFrame[1] = (byte) ((offset >>> 16) & 0xFF);
    currentFrame[2] = (byte) ((offset >>> 8) & 0xFF);
    currentFrame[3] = (byte) (offset & 0xFF);

    // Encode the number of locals.
    currentFrame[4] = (byte) ((numLocal >>> 24) & 0xFF);
    currentFrame[5] = (byte) ((numLocal >>> 16) & 0xFF);
    currentFrame[6] = (byte) ((numLocal >>> 8) & 0xFF);
    currentFrame[7] = (byte) (numLocal & 0xFF);

    // Encode the number of stack entries.
    currentFrame[8] = (byte) ((numStack >>> 24) & 0xFF);
    currentFrame[9] = (byte) ((numStack >>> 16) & 0xFF);
    currentFrame[10] = (byte) ((numStack >>> 8) & 0xFF);
    currentFrame[11] = (byte) (numStack & 0xFF);

    // The next writable index is immediately after the header.
    return FRAME_HEADER_BYTES;
}

