protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new ArrayList<>();
    try {
        // Validate input
        if (start < 0 || end < 0) {
            throw new IllegalArgumentException("Start and end times must be non‑negative");
        }
        if (start > end) {
            throw new IllegalArgumentException("Start time must be less than or equal to end time");
        }
        if (FETCH_DATA_DURATION <= 0) {
            throw new IllegalArgumentException("FETCH_DATA_DURATION must be positive");
        }

        // No range to split if start equals end
        if (start == end) {
            return ranges;
        }

        long current = start;
        while (current < end) {
            long next = Math.min(current + FETCH_DATA_DURATION, end);
            // Avoid zero‑length ranges
            if (next == current) {
                // This can happen only if FETCH_DATA_DURATION is 0, which should have been caught already
                break;
            }
            ranges.add(new TimeRange(current, next));
            current = next;
        }
    } catch (Exception e) {
        // Wrap and rethrow to signal a failure in range construction
        throw new RuntimeException("Failed to build time ranges from " + start + " to " + end, e);
    }
    return ranges;
}

