static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be > 0");
    }
    if (timeBucket <= 0) {
        throw new IllegalArgumentException("timeBucket must be positive");
    }
    long year = timeBucket / 10000;
    long rem = timeBucket % 10000;
    int month = (int) (rem / 100);
    int day = (int) (rem % 100);
    if (year == 0 || month < 1 || month > 12 || day < 1 || day > 31) {
        throw new IllegalArgumentException("Invalid timeBucket format");
    }
    // Adjust day to start of the dayStep bucket
    int newDay = ((day - 1) / dayStep) * dayStep + 1;
    // Basic month length validation for start day (simplified)
    int maxDay = java.time.YearMonth.of((int) year, month).lengthOfMonth();
    if (newDay > maxDay) {
        // fallback to last valid day of month
        newDay = maxDay;
    }
    return year * 10000L + month * 100L + newDay;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("String is null");
    }
    final int strLen = str.length();
    if (index < 0 || len < 0 || index > strLen || index + len > strLen) {
        throw new IndexOutOfBoundsException(
            "Index=" + index + ", len=" + len + ", strLen=" + strLen);
    }
    int bytes = 0;
    int end = index + len;
    for (int i = index; i < end; ) {
        char ch = str.charAt(i);
        int cp;
        if (Character.isHighSurrogate(ch)) {
            if (i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))) {
                cp = Character.toCodePoint(ch, str.charAt(i + 1));
                i += 2;
            } else {
                // Unpaired high surrogate
                cp = 0xFFFD; // Unicode replacement character
                i += 1;
            }
        } else if (Character.isLowSurrogate(ch)) {
            // Unpaired low surrogate
            cp = 0xFFFD; // Unicode replacement character
            i += 1;
        } else {
            cp = ch;
            i += 1;
        }

        if (cp <= 0x7F) {
            bytes += 1;
        } else if (cp <= 0x7FF) {
            bytes += 2;
        } else if (cp <= 0xFFFF) {
            bytes += 3;
        } else {
            bytes += 4;
        }
    }
    return bytes;
}

