public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    // Validate parameters
    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength must be non-negative");
    }
    if (byteArrayValue != null) {
        if (byteOffset < 0 || byteOffset > byteArrayValue.length) {
            throw new IndexOutOfBoundsException("byteOffset out of bounds");
        }
        if (byteOffset + byteLength > byteArrayValue.length) {
            throw new IndexOutOfBoundsException("byteOffset + byteLength exceeds source array length");
        }
    } else if (byteLength > 0) {
        // If byteArrayValue is null we will insert zero-bytes; byteLength must be defined
    }

    // Ensure internal storage has enough capacity
    if (buffer == null) {
        buffer = new byte[Math.max(16, byteLength)];
    }
    int currentPos = this.pos; // current write position
    int required = currentPos + byteLength;
    if (required > buffer.length) {
        int newCap = Math.max(buffer.length << 1, required);
        byte[] newBuffer = new byte[newCap];
        if (buffer.length > 0) {
            System.arraycopy(buffer, 0, newBuffer, 0, buffer.length);
        }
        buffer = newBuffer;
    }

    // Copy or fill bytes
    if (byteArrayValue == null) {
        for (int i = currentPos; i < required; i++) {
            buffer[i] = 0;
        }
    } else {
        System.arraycopy(byteArrayValue, byteOffset, buffer, currentPos, byteLength);
    }

    // Update position
    this.pos = required;
    return this;
}

