public static String findAndSubst(String key, Properties props) {
    if (key == null) {
        throw new IllegalArgumentException("key must not be null");
    }
    if (props == null) {
        throw new IllegalArgumentException("props must not be null");
    }

    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }

    // Regular expression to find placeholders of the form ${var}
    java.util.regex.Pattern pattern = java.util.regex.Pattern.compile("\\$\\{([^}]+)\\}");
    try {
        java.util.regex.Matcher matcher = pattern.matcher(value);
        java.lang.StringBuffer sb = new java.lang.StringBuffer();
        while (matcher.find()) {
            String varName = matcher.group(1);
            String replacement = props.getProperty(varName);
            if (replacement == null) {
                // Fallback to system property if not found in props
                replacement = System.getProperty(varName);
                if (replacement == null) {
                    // If still not found, replace with empty string
                    replacement = "";
                }
            }
            // Ensure that replacement text is treated literally
            replacement = java.util.regex.Matcher.quoteReplacement(replacement);
            matcher.appendReplacement(sb, replacement);
        }
        matcher.appendTail(sb);
        return sb.toString();
    } catch (Exception e) {
        // If any exception occurs during substitution, return the original value
        return value;
    }
}

protected void appendDetail(StringBuffer buffer, String fieldName, int[] array) {
