    }
    if (array == null) {
        buffer.append(fieldName).append("=<null>");
        return;
    }
    buffer.append(fieldName).append('=');
    if (array.length == 0) {
        buffer.append("[]");
    } else {
        buffer.append('[');
        for (int i = 0; i < array.length; i++) {
            if (i > 0) {
                buffer.append(", ");
            }
            buffer.append(array[i]);
        }
        buffer.append(']');
    }
}

