    if (targetVertex == null) {
        throw new IllegalArgumentException("Target vertex cannot be null");
    }
    if (e == null) {
        throw new IllegalArgumentException("Edge cannot be null");
    }

    /* 
     * The data structure that holds the index is assumed to be a 
     * Map that maps a source vertex to another Map that maps a target 
     * vertex to a collection of edges.  The field name is expected to be
     * 'index'; adjust if a different name is used in the surrounding class.
