     * Example:
     *   protected Map<V, Map<V, Set<E>>> index = new HashMap<>();
     */

    // Retrieve or create the map for the source vertex
    Map<V, Set<E>> targetMap = index.computeIfAbsent(sourceVertex, k -> new HashMap<>());

    // Retrieve or create the edge set for the target vertex
    Set<E> edgeSet = targetMap.computeIfAbsent(targetVertex, k -> new HashSet<>());

    // Add the edge to the set
    edgeSet.add(e);
}

private static File[] classPath() {
