    if (classpath == null || classpath.isEmpty()) {
        return new File[0];
    }
    String sep = File.pathSeparator;
    String[] parts = classpath.split(sep, -1);
    int count = 0;
    for (String part : parts) {
        if (!part.isEmpty()) {
            count++;
        }
    }
    File[] files = new File[count];
    int idx = 0;
    for (String part : parts) {
        if (!part.isEmpty()) {
            files[idx++] = new File(part);
        }
    }
    return files;
}

