public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    if (box == null) {
        throw new IllegalArgumentException("box cannot be null");
    }

    double width = box.width;
    double height = box.height;
    double x = box.x;
    double y = box.y;

    if (width <= 0 || height <= 0) {
        throw new IllegalArgumentException("box dimensions must be positive");
    }

    double halfWidth = width / 2.0;
    double leftX = x;
    double rightX = x + halfWidth;

    Box2D leftBox = new Box2D(leftX, y, halfWidth, height);
    Box2D rightBox = new Box2D(rightX, y, width - halfWidth, height);

    return new Pair<>(leftBox, rightBox);
}

private void enlarge(final int size) {
    // Reject non‑positive requests to avoid silent errors.
    if (size <= 0) {
        throw new IllegalArgumentException("Size to enlarge must be positive");
    }

    // Current capacity of the internal byte array.
    int oldCapacity = data.length;

    // Determine a new capacity that is at least as large as required.
    // Grow at least twice as much as current (to amortize copies) or
    // add the requested size, whatever is larger.
    int newCapacity = oldCapacity == 0 ? size
                     : Math.max(oldCapacity << 1, oldCapacity + size);

    // Allocate the new array and copy the existing data.
    byte[] newData = new byte[newCapacity];
    System.arraycopy(data, 0, newData, 0, oldCapacity);

    // Replace the old array reference with the new one.
    data = newData;
}

