private void putAbstractTypes(final int start, final int end) {
    if (start < 0 || end > currentFrame.length || start > end) {
        throw new IllegalArgumentException("Invalid start or end index for currentFrame");
    }
    for (int i = start; i < end; i++) {
        Object type = currentFrame[i];
        try {
            if (type instanceof String) {
                String desc = (String) type;
                // Handle primitive descriptors
                switch (desc) {
                    case "I": // int
                    case "F": // float
                    case "J": // long
                    case "D": // double
                        stackMapTableEntries.add(descriptorToCode(desc));
                        break;
                    case "V":
                        // void should never appear as a stack map entry
                        break;
                    default:
                        // Object or array type
                        if (desc.startsWith("L") || desc.startsWith("[")) {
                            stackMapTableEntries.add((byte) 7); // OBJECT
                        } else {
                            throw new IllegalArgumentException("Unsupported type descriptor: " + desc);
                        }
                }
            } else if (type instanceof Integer) {
                // Primitive numeric type placeholder; this branch can be extended if needed
                stackMapTableEntries.add((byte) 1); // INTEGER
            } else {
                throw new IllegalArgumentException("Unsupported type object: " + type);
            }
        } catch (Exception e) {
            throw new IllegalStateException("Failed to encode verification_type_info for type at index " + i, e);
        }
    }
}

private byte descriptorToCode(final String desc) {
    switch (desc) {
        case "I": return 1; // INTEGER
        case "F": return 2; // FLOAT
