}

public static boolean containsAnyIgnoreCase(String str, List<String> searchStrArray) {
    try {
        if (str == null || searchStrArray == null || searchStrArray.isEmpty()) {
            return false;
        }

        Set<Character> searchChars = new HashSet<>();
        for (String part : searchStrArray) {
            if (part == null) {
                continue;
            }
            char[] chars = part.toLowerCase(Locale.ROOT).toCharArray();
            for (char c : chars) {
                searchChars.add(c);
            }
        }

        if (searchChars.isEmpty()) {
            return false;
        }

        char[] textChars = str.toLowerCase(Locale.ROOT).toCharArray();
        for (char c : textChars) {
            if (searchChars.contains(c)) {
                return true;
            }
        }
        return false;
    } catch (Exception e) {
        // In case of any unexpected error, return false rather than propagating the exception
        return false;
    }
