private static int digitValue(final char c){
    // Return numeric value of an ASCII digit or letter up to base 36.
    // '0' - '9' -> 0 - 9
    // 'a' - 'z' or 'A' - 'Z' -> 10 - 35
    // All other characters return -1 to indicate invalid digit.
    if (c >= '0' && c <= '9') {
        return c - '0';
    }
    if (c >= 'a' && c <= 'z') {
        return c - 'a' + 10;
    }
    if (c >= 'A' && c <= 'Z') {
        return c - 'A' + 10;
    }
    return -1;
}

