public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    int len = str.length();
    StringBuilder sb = new StringBuilder(len);
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c == '\\' && i + 1 < len) {
            char next = str.charAt(i + 1);
            switch (next) {
                case 'b':
                    sb.append('\b');
                    i++;
                    break;
                case 't':
                    sb.append('\t');
                    i++;
                    break;
                case 'n':
                    sb.append('\n');
                    i++;
                    break;
                case 'f':
                    sb.append('\f');
                    i++;
                    break;
                case 'r':
                    sb.append('\r');
                    i++;
                    break;
                case '\"':
                    sb.append('\"');
                    i++;
                    break;
                case '\'':
                    sb.append('\'');
                    i++;
                    break;
                case '\\':
                    sb.append('\\');
                    i++;
                    break;
                case 'u':
                    // Unicode escape (\uXXXX)
                    if (i + 6 <= len) {
                        String hex = str.substring(i + 2, i + 6);
                        try {
                            int codePoint = Integer.parseInt(hex, 16);
                            sb.append((char) codePoint);
                            i += 5; // total step: backslash + 'u' + 4 hex digits = 6 chars, we already processed i=backslash, so increment by 5 more
                        } catch (NumberFormatException e) {
                            throw new Exception("Invalid Unicode escape sequence: \\u" + hex, e);
                        }
                    } else {
                        throw new Exception("Incomplete Unicode escape sequence at position " + i);
                    }
                    break;
                default:
                    // Unknown escape sequence: keep the next char as is
                    sb.append(next);
                    i++;
                    break;
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

private static String javaCharset(String charset) {
    if (charset == null) {
        return null;
    }
    String trimmed = charset.trim();
    if (trimmed.isEmpty()) {
        return trimmed;
    }
    // Map of common MIME charset names to Java equivalents
    switch (trimmed.toLowerCase(Locale.ROOT)) {
        case "utf-8":
        case "utf8":
            return "UTF-8";
        case "iso-8859-1":
        case "iso8859-1":
        case "latin1":
            return "ISO-8859-1";
        case "iso-8859-2":
        case "iso8859-2":
            return "ISO-8859-2";
        case "iso-8859-15":
        case "iso8859-15":
            return "ISO-8859-15";
        case "windows-1252":
        case "cp1252":
            return "windows-1252";
        case "windows-1251":
        case "cp1251":
            return "windows-1251";
        case "gb2312":
        case "gbk":
            return trimmed.toUpperCase(Locale.ROOT); // these are already standard
        case "us-ascii":
        case "ascii":
            return "US-ASCII";
        case "iso-8859-5":
        case "iso8859-5":
            return "ISO-8859-5";
        default:
            // For names not explicitly mapped, return the original trimmed value.
            // Java will resolve it when used with Charset.forName().
            return trimmed;
    }
}

