            throw new IllegalArgumentException("newArrayComponentType must not be null when array is null");
        }
        return java.lang.reflect.Array.newInstance(newArrayComponentType, 1);
    }
    Class<?> arrayClass = array.getClass();
    if (!arrayClass.isArray()) {
        throw new IllegalArgumentException("array must be an array");
    }
    int length = java.lang.reflect.Array.getLength(array);
    Class<?> componentType = arrayClass.getComponentType();
    Object newArray = java.lang.reflect.Array.newInstance(componentType, length + 1);
    for (int i = 0; i < length; i++) {
        java.lang.reflect.Array.set(newArray, i, java.lang.reflect.Array.get(array, i));
    }
    return newArray;
}

private int computeBinaryLog(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer");
    }
    // Integer.numberOfLeadingZeros returns the number of leading zero bits
    // in the 32‑bit representation of n. Subtracting from 32 gives the
    // number of bits needed to represent n, which is floor(log2(n)) + 1.
    return 32 - Integer.numberOfLeadingZeros(n);
}

private Set<V> intersection(Set<V> set1, Set<V> set2) {
    if (set1 == null || set2 == null) {
        return new HashSet<>();
    }
    // Identify the smaller set for efficient iteration
    Set<V> smaller = set1.size() <= set2.size() ? set1 : set2;
    Set<V> larger = set1.size() <= set2.size() ? set2 : set1;

    Set<V> result = new HashSet<>(smaller.size());
    for (V element : smaller) {
        if (larger.contains(element)) {
            result.add(element);
        }
    }
    return result;
}

