protected int removeUnusedNodes(){
    int removedCount = 0;
    try {
        // If the tree does not have a root, nothing to do
        if (this.root == null) {
            return 0;
        }
        // If the root itself is inactive, drop the entire tree
        if (!this.root.isActive()) {
            this.root = null;
            return 1;
        }
        removedCount = removeFromNode(this.root, null);
    } catch (Exception e) {
        // In case of any unexpected runtime issue, we return 0
        return 0;
    }
    return removedCount;
}

/**
 * Recursive helper that removes inactive nodes from the subtree
 * rooted at {@code node}.  It returns the number of nodes removed
 * from that subtree.
 */
private int removeFromNode(Category node, Category parent){
    if (node == null) {
        return 0;
    }
    // If this node is inactive, remove it from its parent's children list
    if (!node.isActive()){
        if (parent != null) {
            parent.getChildren().remove(node);
        }
        return 1; // current node removed
    }

    // Otherwise, recursively process the children.
    int removed = 0;
    List<Category> children = node.getChildren();
    for (int i = 0; i < children.size(); ) {
        Category child = children.get(i);
        int childRemoved = removeFromNode(child, node);
        removed += childRemoved;
        // If the child remained active, move to the next index.
        // If it was removed, the list size decreased; hence keep i unchanged.
        if (child.isActive()){
            i++;
        }
    }
    return removed;
}

