public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength must be non-negative");
    }
    if (byteLength == 0) {
        return this;
    }

    // Validate parameters for non-null array
    if (byteArrayValue != null) {
        if (byteOffset < 0 || byteOffset > byteArrayValue.length) {
            throw new IndexOutOfBoundsException("byteOffset " + byteOffset + " is out of bounds for array length " + byteArrayValue.length);
        }
        if (byteOffset + byteLength > byteArrayValue.length) {
            throw new IndexOutOfBoundsException("byteOffset + byteLength (" + (byteOffset + byteLength)
                    + ") exceeds array length " + byteArrayValue.length);
        }
    }

    // Ensure buffer has enough capacity
    int newLength = this.length + byteLength;
    if (newLength > this.buf.length) {
        int newCap = Math.max(newLength, this.buf.length * 2);
        this.buf = java.util.Arrays.copyOf(this.buf, newCap);
    }

    // Copy data or fill zeros if byteArrayValue is null
    if (byteArrayValue != null) {
        System.arraycopy(byteArrayValue, byteOffset, this.buf, this.length, byteLength);
    } else {
        java.util.Arrays.fill(this.buf, this.length, this.length + byteLength, (byte) 0);
    }

    this.length = newLength;
    return this;
}

