public byte readByte() throws IOException {
    // Ensure there is data to read; if the buffer is exhausted, refill it
    if (buffer == null || buffer.length == 0) {
        throw new IOException("Underlying buffer is uninitialized");
    }

    if (pos >= limit) {
        int bytesRead = in.read(buffer);
        if (bytesRead <= 0) { // (-1 indicates EOF, 0 should not happen but treat as EOF)
            throw new IOException("End of stream reached");
        }
        limit = bytesRead;
        pos = 0;
    }

    return buffer[pos++];
}

@Override public Action inspect(AtmosphereResource r){
    if (r == null) {
        return Action.CONTINUE;
    }
    try {
        AtmosphereResource.TRANSPORT transport = r.getTransport();
        if (transport == null) {
            return Action.CONTINUE;
        }
        switch (transport) {
            case WEBSOCKET:
                // WebSocket connections are naturally event driven; no suspension needed
                break;
            case EVENT_SOURCE:
                // Server-Sent Events – suspend indefinitely
                r.suspend();
                break;
            case LONG_POLLING:
            case LONG_POLL:
                // Long polling – suspend until the next request
                r.suspend();
                break;
            default:
                // For any other transport, simply suspend
                r.suspend();
                break;
        }
    } catch (Exception e) {
        // Fail silently – the action will still be CONTINUE
    }
    return Action.CONTINUE;
}

