    // Handle reference equality
    if (aObj1 == aObj2) {
        return 0;
    }
    // Handle nulls – treat null as less than any non‑null
    if (aObj1 == null) {
        return -1;
    }
    if (aObj2 == null) {
        return 1;
    }
    // If both objects are Comparable and of the same runtime class,
    // attempt to use their natural ordering.
    if (aObj1 instanceof Comparable && aObj2 instanceof Comparable
            && aObj1.getClass() == aObj2.getClass()) {
        try {
            @SuppressWarnings("unchecked")
            Comparable<Object> c1 = (Comparable<Object>) aObj1;
            return c1.compareTo(aObj2);
        } catch (ClassCastException e) {
            // fall back to string comparison below
        }
    }
    // Fallback: compare string representations
    try {
        String s1 = aObj1.toString();
        String s2 = aObj2.toString();
        return s1.compareTo(s2);
    } catch (Exception e) {
        // Last resort: compare hash codes if toString throws or is not unique
        return Integer.compare(aObj1.hashCode(), aObj2.hashCode());
    }
}

