private String unescapeId(String input) {
    if (input == null) {
        return null;
    }
    int len = input.length();
    if (len == 0) {
        return input;
    }

    int start = 0;
    int end = len;

    if (len >= 2 && input.charAt(0) == '"' && input.charAt(len - 1) == '"') {
        start = 1;
        end = len - 1;
    }

    StringBuilder result = new StringBuilder(end - start);

    for (int i = start; i < end; i++) {
        char c = input.charAt(i);
        if (c == '\\' && i + 1 < end) {
            i++;
            char next = input.charAt(i);
            switch (next) {
                case 'n':
                    result.append('\n');
                    break;
                case 't':
                    result.append('\t');
                    break;
                case 'b':
                    result.append('\b');
                    break;
                case 'r':
                    result.append('\r');
                    break;
                case 'f':
                    result.append('\f');
                    break;
                case '\\':
                    result.append('\\');
                    break;
                case '"':
                    result.append('"');
                    break;
                case 'x':
                    int hexDigits = 0;
                    int hexValue = 0;
                    while (i + 1 < end && hexDigits < 2) {
                        char hd = input.charAt(i + 1);
                        int digit = Character.digit(hd, 16);
                        if (digit < 0) {
                            break;
                        }
                        i++;
                        hexValue = (hexValue << 4) + digit;
                        hexDigits++;
                    }
                    if (hexDigits > 0) {
                        result.append((char) hexValue);
                    }
                    break;
                default:
                    // Unknown escape: keep the escaped character as is
                    result.append(next);
                    break;
            }
        } else {
            result.append(c);
        }
    }

    return result.toString();
}

