    }
    return result;
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Basic validation
    if (bucketsByLabel == null || labels == null) {
        throw new IllegalArgumentException("Buckets and labels cannot be null.");
    }
    if (minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        throw new IllegalArgumentException("minLabel is out of bounds: " + minLabel);
    }
    if (minLabel >= labels.size()) {
        throw new IllegalArgumentException("minLabel exceeds labels size.");
    }

    // Obtain the buckets. If any bucket is null, treat it as empty.
    Set<Integer> minBucket = bucketsByLabel.get(minLabel);
    if (minBucket == null || minBucket.isEmpty()) {
        // Ensure bucket 0 exists
        if (bucketsByLabel.get(0) == null) {
            bucketsByLabel.set(0, new java.util.HashSet<>());
        }
        // Nothing to move; just clear (if not null) and exit
        if (minBucket != null) {
            minBucket.clear();
        }
        return;
    }

    // Ensure bucket 0 is available
    Set<Integer> zeroBucket = bucketsByLabel.get(0);
    if (zeroBucket == null) {
        zeroBucket = new java.util.HashSet<>();
        bucketsByLabel.set(0, zeroBucket);
    }

    // Move all vertices from the minLabel bucket to bucket 0
    for (Integer vertex : minBucket) {
        if (vertex == null) {
            continue;
        }
        // Add to bucket 0
        zeroBucket.add(vertex);
        // Update label if the vertex index is valid
        if (vertex >= 0 && vertex < labels.size()) {
            labels.set(vertex, 0);
        }
    }

    // Clear the original bucket
    minBucket.clear();
}

