            m.setAccessible(true);
            m.invoke(this, this);
        } catch (NoSuchMethodException ignored) {
            // The container does not provide an adjustHead method; nothing to do.
        } catch (Exception ex) {
            throw new IllegalStateException("Failed to adjust container head", ex);
