private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }
    // Adjust the previous node, if any
    if (node.prev != null) {
        node.prev.next = node.next;
    } else { // node is the head
        head = node.next;
    }
    // Adjust the next node, if any
    if (node.next != null) {
        node.next.prev = node.prev;
    } else { // node is the tail
        tail = node.prev;
    }
    // Detach the node and update size
    node.prev = null;
    node.next = null;
    if (size > 0) {
        size--;
    }
    return true;
}

