    }
    if (from < 0 || to >= arr.length) {
        throw new IllegalArgumentException("Index out of bounds: from=" + from + ", to=" + to);
    }
    if (from >= to) {
        return; // nothing to reverse
    }
    while (from < to) {
        V temp = arr[from];
        arr[from] = arr[to];
        arr[to] = temp;
        from++;
        to--;
    }
}

