public void putAllWriteable(BeanMap map) {
    if (map == null) {
        return;
    }

    // Obtain the property descriptors of the source BeanMap.
    PropertyDescriptor[] srcDescriptors = map.getPropertyDescriptors();
    if (srcDescriptors == null) {
        return;
    }

    for (PropertyDescriptor pd : srcDescriptors) {
        // Ignore properties that are not writable in the source BeanMap.
        if (pd.getWriteMethod() == null) {
            continue;
        }

        String propName = pd.getName();

        try {
            // Retrieve the current value from the source BeanMap.
            Object value = map.get(propName);

            // Ignore values that cannot be read (e.g., read‑only source property).
            if (value == null && pd.getReadMethod() == null) {
                continue;
            }

            // Attempt to set the value into the target BeanMap.
            // Target properties that are not writable will simply throw an exception
            // which we will ignore.
            this.set(propName, value);
        } catch (IllegalArgumentException | NullPointerException | RuntimeException e) {
            // Ignore any errors (e.g., property not writable or incompatible value)
            // and continue copying the remaining properties.
        } catch (Exception e) {
            // Any other unexpected exception should also be ignored to maintain API
            // resilience. Logging could be added here if desired.
        }
    }
}

