            }
            byte[] newBuf = new byte[newCapacity];
            System.arraycopy(buf, 0, newBuf, 0, length);
            buf = newBuf;
        }
        // Put the integer in big-endian order
        buf[length++] = (byte) (intValue >>> 24);
        buf[length++] = (byte) (intValue >>> 16);
        buf[length++] = (byte) (intValue >>> 8);
        buf[length++] = (byte) intValue;
        return this;
    } catch (Exception e) {
        throw new RuntimeException("Failed to put int into ByteVector", e);
    }
}

