public static Type resolveBound(TypeVariable<?> typeVariable) {
    if (typeVariable == null) {
        throw new IllegalArgumentException("typeVariable must not be null");
    }
    try {
        Type[] bounds = typeVariable.getBounds();
        if (bounds == null || bounds.length == 0) {
            return Unknown.class;
        }
        // Iterate through bounds and try to resolve to a Class
        for (Type bound : bounds) {
            if (bound == null) {
                continue;
            }
            if (bound instanceof Class) {
                return bound;
            }
            if (bound instanceof ParameterizedType) {
                Type raw = ((ParameterizedType) bound).getRawType();
                if (raw instanceof Class) {
                    return raw;
                }
            }
            if (bound instanceof WildcardType) {
                WildcardType wc = (WildcardType) bound;
                // Prefer lower bounds if present
                Type[] lower = wc.getLowerBounds();
                if (lower.length > 0 && lower[0] instanceof Class) {
                    return lower[0];
                }
                Type[] upper = wc.getUpperBounds();
                if (upper.length > 0 && upper[0] instanceof Class) {
                    return upper[0];
                }
            }
            if (bound instanceof TypeVariable) {
                Type resolved = resolveBound((TypeVariable<?>) bound);
                if (!(resolved instanceof Unknown)) {
                    return resolved;
                }
            }
        }
    } catch (Exception e) {
        // Swallow any unexpected reflection errors and fall back to Unknown
    }
    return Unknown.class;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        throw new IllegalArgumentException("Graph and vertices set must not be null");
    }
    int size = vertices.size();
    if (size <= 1) {
        return true;
    }
    // Convert to list for indexed access
    List<V> vertexList = new ArrayList<>(vertices);
    for (int i = 0; i < size; i++) {
        V v1 = vertexList.get(i);
        if (v1 == null) {
            throw new IllegalArgumentException("Vertex set contains null");
        }
        for (int j = i + 1; j < size; j++) {
            V v2 = vertexList.get(j);
            if (v2 == null) {
                throw new IllegalArgumentException("Vertex set contains null");
            }
            // For undirected graphs `containsEdge` is symmetric.
            // For directed graphs this checks existence of an edge from v1 to v2.
            if (!graph.containsEdge(v1, v2)) {
                return false;
            }
        }
    }
    return true;
}

private List<Integer> computeLowerBounds(List<K> keys) {
    List<Integer> result = new ArrayList<>();
    if (keys == null) {
        return result;
    }
    for (K key : keys) {
        if (key == null) {
            result.add(null);
            continue;
        }
        // Ensure key is an Integer
        if (!(key instanceof Integer)) {
            throw new IllegalArgumentException("Key is not an Integer: " + key);
        }
        Integer current = (Integer) key;
        Integer best = null;
        for (K other : keys) {
            if (other == null || other == key) {
                continue;
            }
            if (!(other instanceof Integer)) {
                throw new IllegalArgumentException("Other key is not an Integer: " + other);
            }
            Integer candidate = (Integer) other;
            if (candidate < current) {
                if (best == null || candidate > best) {
                    best = candidate;
                }
            }
        }
        result.add(best);
    }
    return result;
}

