    final double TOLERANCE = 1e-9;
    try {
        // If both references are identical, they are equal
        if (p1 == p2) return true;
        // If either point is null, they cannot be equal
        if (p1 == null || p2 == null) return false;
        // Compare both coordinates within the tolerance
        double dx = Math.abs(p1.getX() - p2.getX());
        double dy = Math.abs(p1.getY() - p2.getY());
        return dx <= TOLERANCE && dy <= TOLERANCE;
    } catch (Exception e) {
        // In case of any unexpected runtime failure, consider the points not equal
        return false;
    }
}

