public static String applyRelativePath(String path, String relativePath) {
    // Validate input parameters
    if (path == null) {
        throw new IllegalArgumentException("Base path must not be null");
    }
    if (relativePath == null) {
        throw new IllegalArgumentException("Relative path must not be null");
    }

    // If the relative path is actually an absolute path, return it as is
    if (relativePath.startsWith("/")) {
        return relativePath;
    }

    // Split the base path into components
    String[] baseParts = path.split("/");
    // Use a list to simulate a stack
    java.util.List<String> stack = new java.util.ArrayList<>();
    for (String part : baseParts) {
        if (part.isEmpty() || part.equals(".")) {
            // Skip empty parts and current directory references
            continue;
        }
        if (!part.equals("..")) {
            stack.add(part);
        } else {
            // Handle parent directory reference
            if (!stack.isEmpty()) {
                stack.remove(stack.size() - 1);
            } // else remain at root (do nothing)
        }
    }

    // Process the relative path components
    String[] relParts = relativePath.split("/");
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue; // ignore empty or current dir components
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.remove(stack.size() - 1);
            } // else stay at root
        } else {
            stack.add(part);
        }
    }

    // Build the resulting path
    boolean isAbsolute = path.startsWith("/");
    java.lang.StringBuilder result = new java.lang.StringBuilder();
    if (isAbsolute) {
        result.append("/");
    }
    for (int i = 0; i < stack.size(); i++) {
        result.append(stack.get(i));
        if (i < stack.size() - 1) {
            result.append("/");
        }
    }

    // If result is empty and was relative, return "." (current directory)
    if (!isAbsolute && result.length() == 0) {
        return ".";
    }

    return result.toString();
}

