public static int indexOfExtension(String filename){
    if (filename == null) {
        return -1;
    }
    int lastDot = filename.lastIndexOf('.');
    if (lastDot == -1) {
        return -1;
    }
    // Find the last file separator (works for both Unix '/' and Windows '\\')
    int lastUnixSep = filename.lastIndexOf('/');
    int lastWindowsSep = filename.lastIndexOf('\\');
    int lastSep = Math.max(lastUnixSep, lastWindowsSep);
    return (lastDot > lastSep) ? lastDot : -1;
}

public boolean isExpired(long timestamp, long expiredThreshold) {
    // Sanity checks – a non‑positive threshold means never expire
    if (expiredThreshold <= 0) {
        return false;
    }
    try {
        long current = System.currentTimeMillis();
        // If the current time is more than the threshold after the
        // provided timestamp, the metrics are considered expired.
        // A negative difference (timestamp in the future) should not
        // cause expiration.
        return (current - timestamp) > expiredThreshold;
    } catch (Throwable t) {
        // In case of any unexpected runtime issue, conservatively
        // decide not to expire to avoid accidental cache removal.
        return false;
    }
}

Edge edgeToNext() {
    // Retrieve the previously returned node and the node that will be returned next
    Node prevNode = this.prevNode; // previously returned node
    Node nextNode = this.nextNode; // node that will be returned next

    // If either node is missing, we cannot create an edge
    if (prevNode == null || nextNode == null) {
        return null;
    }

    // If either node is virtual, replace it with its real counterpart
    if (prevNode.isVirtual()) {
        try {
            prevNode = prevNode.getRealNode();
        } catch (Exception e) {
            // If unable to resolve to a real node, return null
            return null;
        }
    }

    if (nextNode.isVirtual()) {
        try {
            nextNode = nextNode.getRealNode();
        } catch (Exception e) {
            // If unable to resolve to a real node, return null
            return null;
        }
    }

    // Construct and return the edge between the two (real) nodes
    try {
        return new Edge(prevNode, nextNode);
    } catch (Exception e) {
        // Safely propagate any construction failures
        return null;
    }
}

public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    // Validate inputs
    if (str == null || substring == null) {
        return false;
    }
    if (index < 0) {
        return false;
    }

    int strLen = str.length();
    int subLen = substring.length();

    // If the substring is empty, it matches at any position up to the end of str
    if (subLen == 0) {
        return index <= strLen;
    }

    // Check bounds: the last character of the substring must fit within str
    if (index > strLen - subLen) {
        return false;
    }

    // Compare characters one by one
    for (int i = 0; i < subLen; i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }

    return true;
}

protected void append(LoggingEvent event) {
