    if (event == null) {
        return;
    }

    // Obtain a formatted message.  If a Layout is configured, use it;
    // otherwise fall back to the event's message string.
    String formattedMessage;
    try {
        if (layout != null) {
            formattedMessage = layout.format(event);
        } else {
            formattedMessage = event.getMessage() != null
                    ? event.getMessage().toString()
                    : "";
        }
