                continue;
            }
        } catch (IOException ioEx) {
            // If we cannot write to this client, remove it from the collection
            it.remove();
        } catch (RuntimeException rtEx) {
            // Unexpected runtime errors – skip this client but keep others alive
            it.remove();
        }
